<script setup lang="ts">
import { enterPrivateCard, catalogueAdRows } from '../../shared/adsense-policy.mjs'
import { gameFromCardId } from '../../shared/games.mjs'
function selectCard(id: string) {
  if (!enterPrivateCard(window, id)) selected.value = id
}
const api = useApi(), notice = useNotice(), route = useRoute()
const filters = reactive({ game: '', q: '', set: typeof route.query.set === 'string' ? route.query.set : '', language: '', rarity: '', artist: '', dex: '', ownership: ['owned', 'missing', 'wishlist'].includes(String(route.query.ownership)) ? String(route.query.ownership) : 'all', sort: 'number' })
const page = ref(1), view = ref('grid'), facets = ref<any>({ sets: [], rarities: [] }), result = ref<any>({ items: [], total: 0, limit: 30 }), loading = ref(true), selected = ref<string | null>(null), loadError = ref('')
const gridRows = computed<any[]>(() => catalogueAdRows(result.value.items))
const tabs = [{ value: 'all', label: 'All cards' }, { value: 'owned', label: 'Owned' }, { value: 'missing', label: 'Missing' }, { value: 'wishlist', label: 'Wishlist' }]
let timer: ReturnType<typeof setTimeout> | undefined, sequence = 0, alive = true
async function loadFacets() {
  try { const data = await api('/api/catalogue/facets'); if (alive) facets.value = data }
  catch (e) { if (alive) notice.show(errorMessage(e), 'error') }
}
async function load() {
  const request = ++sequence; loading.value = true; loadError.value = ''
  try { const data = await api('/api/catalogue', { query: { ...filters, page: page.value } }); if (request === sequence) result.value = data }
  catch (e) { if (request === sequence) loadError.value = errorMessage(e) }
  finally { if (request === sequence) loading.value = false }
}
const visibleSets = computed<any[]>(() => facets.value.sets.filter((set: any) => !filters.game || set.game === filters.game))
const activeFilterCount = computed(() => [filters.language, filters.rarity, filters.artist, filters.dex, filters.sort !== 'number' ? filters.sort : ''].filter(Boolean).length)
watch(() => route.query.ownership, value => { filters.ownership = ['owned', 'missing', 'wishlist'].includes(String(value)) ? String(value) : 'all' })
watch(() => filters.game, () => { filters.set = ''; filters.dex = ''; filters.language = '' })
watch(filters, () => { page.value = 1; clearTimeout(timer); timer = setTimeout(load, 250) })
watch(page, () => { clearTimeout(timer); load() })
onMounted(() => {
  if (route.query.ads === 'off' && typeof route.query.card === 'string') {
    try { if (gameFromCardId(route.query.card)) selected.value = route.query.card } catch { /* Unknown links do not open a private dialog. */ }
  }
  void loadFacets()
  void load()
})
onBeforeUnmount(() => { alive = false; sequence++; clearTimeout(timer) })
function reset() { Object.assign(filters, { game: '', q: '', set: '', language: '', rarity: '', artist: '', dex: '', ownership: 'all', sort: 'number' }) }
</script>
<template><header class="page-heading compact-heading"><div><h1>Cards</h1></div><div class="button-row"><span class="badge purple">{{ result.total.toLocaleString() }} matching cards</span><NuxtLink to="/scan" class="button primary"><AppIcon name="search" :size="17" />Scan a card</NuxtLink></div></header><section class="panel catalogue-controls"><div class="search-row"><label class="search-field"><AppIcon name="search" /><input v-model="filters.q" placeholder="Search name or card number…" aria-label="Search cards" /></label><div class="segmented"><button :class="{ active: view === 'grid' }" aria-label="Grid view" :aria-pressed="view === 'grid'" @click="view = 'grid'"><AppIcon name="grid" :size="18" /></button><button :class="{ active: view === 'list' }" aria-label="List view" :aria-pressed="view === 'list'" @click="view = 'list'"><AppIcon name="list" :size="18" /></button></div></div><div class="filter-row primary-filters"><GamePicker v-model="filters.game" all /><label>Set<select v-model="filters.set"><option value="">All imported sets</option><option v-for="set in visibleSets" :key="set.id" :value="set.id">{{ set.name }} ({{ set.language.toUpperCase() }})</option></select></label></div><UiDisclosure class="catalogue-more-filters" title="More filters" :hint="activeFilterCount ? activeFilterCount + ' active' : ''"><div class="filter-row"><label>Language<select v-model="filters.language"><option value="">All languages</option><option value="en">English</option><option v-if="!filters.game || filters.game === 'pokemon'" value="ja">Japanese</option></select></label><label>Rarity<select v-model="filters.rarity"><option value="">All rarities</option><option v-for="rarity in facets.rarities" :key="rarity">{{ rarity }}</option></select></label><label>Sort by<select v-model="filters.sort"><option value="number">Set & card number</option><option value="name">Card name</option></select></label><label>Illustrator<input v-model="filters.artist" placeholder="e.g. Mitsuhiro Arita" /></label><label v-if="!filters.game || filters.game === 'pokemon'">Pokédex number<input v-model="filters.dex" type="number" min="1" max="10000" placeholder="e.g. 25" /></label></div></UiDisclosure><button v-if="filters.q || filters.game || filters.set || activeFilterCount || filters.ownership !== 'all'" class="text-button clear-catalogue-filters" @click="reset">Clear filters</button></section><div class="catalogue-tabs"><div class="tab-list" role="group" aria-label="Collection filter"><button v-for="tab in tabs" :key="tab.value" :class="{ active: filters.ownership === tab.value }" @click="filters.ownership = tab.value">{{ tab.label }}</button></div><span class="muted small">{{ loading ? 'Loading…' : 'Page ' + page + ' of ' + Math.max(1, Math.ceil(result.total / result.limit)) }}</span></div><p v-if="loadError" class="alert error">{{ loadError }}<button class="text-button" @click="load">Retry</button></p><div v-if="loading && !result.items.length" class="loading-panel">Loading your catalogue…</div><div v-else-if="!result.items.length" class="empty-state"><div class="empty-icon"><AppIcon name="search" :size="36" /></div><h3>No cards here yet.</h3><p>Try a different search, or import a set in Game imports.</p><button class="button secondary" @click="reset">Reset filters</button></div><div v-else-if="view === 'grid'" class="card-grid" :class="{ updating: loading }"><template v-for="row in gridRows" :key="row.key"><AdSenseSlot v-if="row.kind === 'ad'" :content-ready="result.items.length > 0 && !loadError && !selected" grid auto-only /><CardTile v-else :card="row.item" @select="selectCard($event)" /></template></div><div v-else class="panel table-scroll"><table class="card-table"><thead><tr><th>Card</th><th>Set</th><th>Printing summary</th><th>Owned copies</th></tr></thead><tbody><tr v-for="card in result.items" :key="card.id"><td><button class="table-card-button" @click="selectCard(card.id)"><CardImage :card="card" alt="" /><span><strong>{{ card.name }}</strong><small>#{{ card.local_id }} · {{ card.language.toUpperCase() }}</small></span></button></td><td>{{ card.set_name }}</td><td>{{ card.rarity || 'Not supplied' }}<span v-if="card.wishlist" class="badge">Wishlist</span></td><td><span class="badge" :class="card.quantity > 0 ? 'green' : ''">{{ card.quantity }}</span></td></tr></tbody></table></div><div v-if="result.total > result.limit" class="pagination"><button class="button secondary" :disabled="page <= 1 || loading" @click="page--"><AppIcon name="left" :size="16" />Previous</button><span>Page {{ page }} / {{ Math.ceil(result.total / result.limit) }}</span><button class="button secondary" :disabled="page * result.limit >= result.total || loading" @click="page++">Next<AppIcon name="right" :size="16" /></button></div><AdSenseSlot v-if="view === 'list'" :content-ready="result.items.length > 0 && !loadError && !selected" auto-only /><CardDialog :card-id="selected" @close="selected = null" @saved="load" /></template>

<style scoped>
.compact-heading{margin-bottom:18px}.compact-heading h1{font-size:28px}.catalogue-controls{padding:18px 22px}.primary-filters{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:14px}.primary-filters>label{min-width:0}.primary-filters select{width:100%;min-width:0}.catalogue-more-filters{margin-top:8px}.catalogue-more-filters .filter-row{margin:0}.clear-catalogue-filters{font-size:12px;min-height:40px}.catalogue-tabs .tab-list{overflow-x:auto;white-space:nowrap}.catalogue-tabs .tab-list button{min-height:44px;flex-shrink:0}
@media(max-width:600px){.compact-heading h1{font-size:24px}.catalogue-controls{padding:14px}.primary-filters{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:10px}.primary-filters>label{font-size:11px}.primary-filters select{padding:10px 7px}.catalogue-more-filters .filter-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.catalogue-more-filters .filter-row>label{min-width:0}.catalogue-more-filters input,.catalogue-more-filters select{min-width:0;width:100%}.catalogue-tabs{gap:8px}.catalogue-tabs .tab-list{gap:18px;max-width:100%}}
</style>
